import re, urllib.request

def get_espn_squad(team_id, slug):
    url = f'https://www.espn.com/soccer/team/squad/_/id/{team_id}/{slug}'
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 ...'})
    with urllib.request.urlopen(req, timeout=15) as resp:
        html = resp.read().decode('utf-8', errors='ignore')
    rows = re.findall(r'<tr class="Table__TR[^"]*"[^>]*>(.*?)</tr>', html, re.DOTALL)
    role_map = {'G': 'goalkeepers', 'D': 'defenders', 'M': 'midfielders', 'F': 'forwards'}
    squad = {'goalkeepers': [], 'defenders': [], 'midfielders': [], 'forwards': []}
    for row in rows:
        cells = re.findall(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)
        if len(cells) >= 2:
            name = re.sub(r'<[^>]+>', '', cells[0]).strip()
            pos = re.sub(r'<[^>]+>', '', cells[1]).strip()
            if name and name != 'Name' and pos in role_map:
                squad[role_map[pos]].append(name)
    return squad
